int len_alloced;
main(int argc, char** argv) {
  /* The offset will be system- and compiler-specific */;
  char* ptr = &ptr - 9;
  result = strcpy (malloc(100 + (len_alloced = strlen(ptr))), ptr);
  printf("requested memory = %d\n"
         "copied text = %d\n", len_alloced + 1, strlen(result) + 1);
}

